input [31:0] WriteDataM;
input [4:0] WriteRegM;
input [31:0] mem_data_i;

output RegWriteM_o;
output [31:0] WriteRegData;
output [4:0] WriteRegAddr;
output [31:0] mem_addr;
output mem_we;
output [31:0] mem_wd;

