input clk;
input cen_i;
input oen_i;
input [Addr_Width-1:0] addr_i;
output [Word_Width-1:0] data_o;

// Memory array declaration
reg [Word_Width-1:0] mem_array[(1<<Addr_Width)-1:0];

// Register declaration
reg [Word_Width-1:0] data_r;

// Logic declaration
