         _instr<=0;
         _imm<=0;
         _rd1<=0;
         _rd2<=0;
      end 
      _pcplus<=pcplusD;
   end

   assign instrE=_instr;
   assign immE=_imm;
   assign rd1E=_rd1;
   assign rd2E=_rd2;
   assign pcplusE=_pcplus;

