module top_module(
    input clk,
    input reset,
    input noisy_signal,
    output reg clean_signal);reg [2:0] shift_reg;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            shift_reg <= 3'b000;
            clean_signal <= 0;
        end else begin
            shift_reg <= {shift_reg[1:0], noisy_signal};
            if (shift_reg == 3'b111) begin
                clean_signal <= 1;
            end else if (shift_reg == 3'b000) begin
                clean_signal <= 0;
            end
        end
    end

endmodule

