module top_module(
  input clk,
  input rst,
  input mosi,
  input sck,
  input ss,
  output reg miso
);// Define state variables
  reg [1:0] state;
  reg [7:0] tx_data;
  reg [7:0] rx_data;
  reg [2:0] bit_count;
  reg tx_done;

  // Define constants
  parameter IDLE = 2'b00;
  parameter TX = 2'b01;
  parameter RX = 2'b10;
  parameter COMPLETE = 2'b11;

  // Define state transition logic
  always @(posedge clk, posedge rst) begin
    if (rst) begin
      state <= IDLE;
      tx_data <= 8'b0;
      rx_data <= 8'b0;
      bit_count <= 3'b0;
      tx_done <= 1'b0;
      miso <= 1'b0;
    end else begin
      case (state)
        IDLE: begin
          if (!ss) begin
            state <= TX;
            tx_data <= mosi;
            bit_count <= 3'b0;
          end
        end
        TX: begin
          if (bit_count == 3'b0) begin
            miso <= 1'b0;
          end else begin
            miso <= tx_data[7];
            tx_data <= {tx_data[6:0], 1'b0};
          end
          bit_count <= bit_count + 1;
          if (bit_count == 3'b100) begin
            state <= RX;
            bit_count <= 3'b0;
          end
        end
        RX: begin
          if (bit_count == 3'b0) begin
            miso <= 1'b0;
          end else begin
            rx_data <= {rx_data[6:0], mosi};
          end
          bit_count <= bit_count + 1;
          if (bit_count == 3'b100) begin
            state <= COMPLETE;
            tx_done <= 1'b1;
            bit_count <= 3'b0;
          end
        end
        COMPLETE: begin
          if (ss) begin
            state <= IDLE;
            miso <= 1'b0;
            tx_done <= 1'b0;
          end
        end
      endcase
    end
  end

endmodule

