module top_module(
	input clk,
	input rst_n,
	output sq_wave
);localparam CLOCK_FREQUENCY = 100000000;


	integer counter = 0;

	reg sq_wave_reg = 0;
	assign sq_wave = sq_wave_reg;

 always @(posedge clk) begin

		if (!rst_n) begin
			counter <= 8'h00;
			sq_wave_reg	 <= 1'b0;
		end

		else begin 


			if (counter == 8'h00) begin
				sq_wave_reg <= ~sq_wave_reg;


				counter <= CLOCK_FREQUENCY/2 - 1;  
			end 


			else 
				counter <= counter - 1; 
			end
		end

endmodule

module top_module(input reset, input wire in_clk,output reg out_clk, input [7:0] ratio);reg [7:0] counter;



   always @(posedge in_clk or posedge reset)
     if(reset)
       counter <= #1 8'd0;
     else if(counter == 0)
       counter <= #1 ratio[7:1] + (ratio[0] & out_clk) - 8'b1;
     else
       counter <= #1 counter-8'd1;

   always @(posedge in_clk or posedge reset)
     if(reset)
       out_clk <= #1 1'b0;
     else if(counter == 0)
       out_clk <= #1 ~out_clk;

endmodule

