module top_module (
  input in1,
  input in2,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter A=0, B=1, C=2, D=3;

    always_comb begin
		case (state)
			A: next_state = (in1 || in2) ? C : B;
			B: next_state = (in1 || in2) ? D : C;
			C: next_state = (in1 || in2) ? A : D;
			D: next_state = (in1 || in2) ? B : A;
		endcase
    end

	assign out = (state==A) || (state==C);

endmodule

