            @(posedge clk);
            #1;
            clr = 0;
            load = 0;
            #1;

            check_outputs(4'b0000);
        end
        endtask

    task testcase007;

        begin
            test_num = test_num + 1;
            $display("Test %0d: Priority - load over sft", test_num);
            reset_dut();
            load = 1;
            dph = 4'b0111;
            sft = 1;
            carry = 1;
            @(posedge clk);
            #1;
            load = 0;
            sft = 0;

            #1;


            check_outputs(4'b0111);
