            reset_dut();

            load = 1; dph = 4'b1000; @(posedge clk); #1;
            load = 0;
            sft = 1; carry = 0;
            repeat(3) @(posedge clk);
            #1;
            sft = 0;
            #1;

            check_outputs(4'b0001);
