code:
module top_module(
  input clk,
  input reset,
  input data,
  output reg enable_counter
);parameter S0 = 2'b00; // idle state
  parameter S1 = 2'b01; // first bit detected
  parameter S2 = 2'b10; // second bit detected
  parameter S3 = 2'b11; // third bit detected

  reg [1:0] state;
  reg [2:0] shift_reg;

  always @(posedge clk) begin
    if (reset) begin
      state <= S0;
      shift_reg <= 0;
      enable_counter <= 0;
    end
    else begin
      case (state)
        S0: begin
          shift_reg <= {shift_reg[1:0], data};
          if (shift_reg == 3'b001) begin
            state <= S1;
          end
        end
        S1: begin
          shift_reg <= {shift_reg[1:0], data};
          if (shift_reg == 3'b010) begin
            state <= S2;
          end
          else if (shift_reg != 3'b001) begin
            state <= S0;
          end
        end
        S2: begin
          shift_reg <= {shift_reg[1:0], data};
          if (shift_reg == 3'b100) begin
            state <= S3;
            enable_counter <= 1;
          end
          else if (shift_reg != 3'b010) begin
            state <= S0;
          end
        end
        S3: begin
          if (enable_counter) begin
            enable_counter <= 0;
          end
          if (shift_reg != 3'b100) begin
            state <= S0;
          end
        end
      endcase
    end
  end

endmodule

