module top_module(
	input clk,
	input reset,
	input [4:0] shift_amount,
	input direction,
	output reg [31:0] q);always @(posedge clk) begin
	if (reset)
		q <= 32'b0;
	else if (direction)
		q <= q << shift_amount;
	else
		q <= q >> shift_amount;
end
endmodule

module gray_counter(
    input clk,
    input rst_n,
    output reg [4:0] count
);
    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            count <= 5'b00000;
        end else begin
            count <= {count[4], count[4] ^ count[3], count[3] ^ count[2], count[2] ^ count[1], count[1] ^ count[0]};
        end
    end
endmodule

