   input                      clk,
   input                      rst,
   output                     done,

   input    [63:0]            start_in,
   input    [63:0]            end_in,
   input    [63:0]            step_in,

   input                      read_in,
   output   [63:0]            count_out
);reg   [63:0]               counter_s;

