module traffic_light_controller (
	input clk,
	input reset,
	output reg [1:0] light_ns,
	output reg [1:0] light_ew);

	parameter NS_GREEN=2'b00, NS_YELLOW=2'b01, EW_GREEN=2'b10, EW_YELLOW=2'b11;
	reg [1:0] state, next_state;
	reg [3:0] counter;

	always @(posedge clk) begin
		if (reset) state <= NS_GREEN;
		else state <= next_state;
	end

	always @(posedge clk) begin
		if (state == next_state) counter <= counter + 1;
		else counter <= 0;
	end

	always_comb begin
		case (state)
			NS_GREEN: next_state = (counter == 4'b1111) ? NS_YELLOW : NS_GREEN;
			NS_YELLOW: next_state = (counter == 4'b1111) ? EW_GREEN : NS_YELLOW;
			EW_GREEN: next_state = (counter == 4'b1111) ? EW_YELLOW : EW_GREEN;
			EW_YELLOW: next_state = (counter == 4'b1111) ? NS_GREEN : EW_YELLOW;
			default: next_state = NS_GREEN;
		endcase
	end

	always @(state) begin
		case (state)
			NS_GREEN: begin
				light_ns = 2'b01;
				light_ew = 2'b00;
			end
			NS_YELLOW: begin
				light_ns = 2'b10;
				light_ew = 2'b00;
			end
			EW_GREEN: begin
				light_ns = 2'b00;
				light_ew = 2'b01;
			end
			EW_YELLOW: begin
				light_ns = 2'b00;
				light_ew = 2'b10;
			end
			default: begin
				light_ns = 2'b00;
				light_ew = 2'b00;
			end
		endcase
	end
endmodule

